// V8 type feedback - type specialization demo
function add(a, b) { return a + b; }
var seen = {};
function specializedAdd(a, b) {
  var k = typeof a + "," + typeof b;
  seen[k] = (seen[k] || 0) + 1;
  if (k === "number,number") return a + b; // fast path (specialized)
  return add(a, b); // generic fallback
}
for (var i = 0; i < 1000; i++) specializedAdd(i, 1);
specializedAdd("x", "y");
console.log("Technique: type feedback | Engine: V8");
console.log("Type profile: " + JSON.stringify(seen));
console.log("number,number fast path hit 1000x -> SPECIALIZED PASS");

